sections.css:
.organic-volume{background: linear-gradient(160deg, var(--surface-top), var(--surface-bottom)); backdrop-filter: blur(80px) saturate(180%); border-radius: 2.5rem; position: relative; isolation: isolate; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; box-shadow: inset 1px 1px 3px var(--shadow-light),
    inset -2px -2px 12px var(--shadow-dark),
    0 30px 60px rgba(0,0,0,0.4); transition: transform 0.8s cubic-bezier(0.16, 1, 0.3, 1), border-radius 0.8s;}
.organic-volume::before{content: ""; position: absolute; inset: -1px; border-radius: inherit; background: radial-gradient(
    800px circle at var(--mouse-x) var(--mouse-y),
    var(--electric-violet),
    transparent 40%
  ); opacity: 0; mix-blend-mode: screen; transition: opacity 0.5s; pointer-events: none; mask: linear-gradient(rgb(255, 255, 255) 0px, rgb(255, 255, 255) 0px) content-box exclude, linear-gradient(rgb(255, 255, 255) 0px, rgb(255, 255, 255) 0px); padding: 1px; z-index: 10;}
.organic-volume::after{content: ""; position: absolute; inset: 0px; border-radius: inherit; box-shadow: rgba(255, 0, 0, 0.05) 2px 0px 8px inset, rgba(0, 0, 255, 0.05) -2px 0px 8px inset; pointer-events: none; opacity: 0.8;}
.organic-volume:hover{transform: translateY(-5px) scale(1.005); border-radius: 2.2rem;}
.organic-volume:hover::before{opacity: 0.4;}
.scroll-reveal{}
.neural-stat{font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace; letter-spacing: -0.04em;}
.chromatic-aberration{text-shadow: rgba(255, 0, 0, 0.3) -1px 0px 2px, rgba(0, 255, 255, 0.3) 1px 0px 2px;}
h2, h3{font-size: inherit; font-weight: inherit;}
h2, h3, p{margin: 0px;}
svg{display: block; vertical-align: middle;}
.absolute{position: absolute;}
.relative{position: relative;}
.inset-0{inset: 0px;}
.left-0{left: 0px;}
.top-0{top: 0px;}
.z-10{z-index: 10;}
.mb-2{margin-bottom: 0.5rem;}
.mb-24{margin-bottom: 6rem;}
.mb-6{margin-bottom: 1.5rem;}
.mt-16{margin-top: 4rem;}
.mt-20{margin-top: 5rem;}
.mt-8{margin-top: 2rem;}
.flex{display: flex;}
.grid{display: grid;}
.h-1{height: 0.25rem;}
.h-full{height: 100%;}
.min-h-\[450px\]{min-height: 450px;}
.w-\[85\%\]{width: 85%;}
.w-full{width: 100%;}
.max-w-lg{max-width: 32rem;}
.auto-rows-auto{grid-auto-rows: auto;}
.grid-cols-1{grid-template-columns: repeat(1, minmax(0px, 1fr));}
.flex-col{flex-direction: column;}
.items-start{align-items: flex-start;}
.items-center{align-items: center;}
.justify-between{justify-content: space-between;}
.gap-8{gap: 2rem;}
.overflow-hidden{overflow: hidden;}
.rounded-full{border-radius: 9999px;}
.bg-\[var\(--shadow-dark\)\]{background-color: var(--shadow-dark);}
.bg-gradient-to-br{background-image: linear-gradient(to bottom right, var(--tw-gradient-stops));}
.bg-gradient-to-r{background-image: linear-gradient(to right, var(--tw-gradient-stops));}
.p-12{padding: 3rem;}
.text-4xl{font-size: 2.25rem; line-height: 2.5rem;}
.text-5xl{font-size: 3rem; line-height: 1;}
.text-\[5\.5rem\]{font-size: 5.5rem;}
.text-lg{font-size: 1.125rem; line-height: 1.75rem;}
.text-sm{font-size: 0.875rem; line-height: 1.25rem;}
.text-xs{font-size: 0.75rem; line-height: 1rem;}
.font-light{font-weight: 300;}
.font-medium{font-weight: 500;}
.uppercase{text-transform: uppercase;}
.leading-\[1\.1\]{line-height: 1.1;}
.leading-relaxed{line-height: 1.625;}
.tracking-\[0\.2em\]{letter-spacing: 0.2em;}
.tracking-\[0\.3em\]{letter-spacing: 0.3em;}
.tracking-tight{letter-spacing: -0.025em;}
.tracking-tighter{letter-spacing: -0.05em;}
.text-\[var\(--amber-glow\)\]{color: var(--amber-glow);}
.text-\[var\(--text-core\)\]{color: var(--text-core);}
.text-\[var\(--text-dim\)\]{color: var(--text-dim);}
.opacity-0{opacity: 0;}
.mix-blend-color-dodge{mix-blend-mode: color-dodge;}
.blur-\[2px\]{--tw-blur: blur(2px); filter: var(--tw-blur) var(--tw-brightness) var(--tw-contrast) var(--tw-grayscale) var(--tw-hue-rotate) var(--tw-invert) var(--tw-saturate) var(--tw-sepia) var(--tw-drop-shadow);}
.transition-opacity{transition-property: opacity; transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1); transition-duration: 150ms;}
.duration-1000{transition-duration: 1000ms;}
.group:hover .group-hover\:opacity-10{opacity: 0.1;}
@media (min-width: 768px){.md\:p-16{padding: 4rem;}}
@media (min-width: 768px){.md\:text-\[3rem\]{font-size: 3rem;}}
